(async()=>{try{const r=await fetch('experiments.json',{cache:'no-store'});if(!r.ok)throw Error('Results unavailable');const d=await r.json(),x=d.experiments.find(e=>e.key==='iphone13pro_4x'),b=d.baseline,n=v=>v==null?'Pending':Number(v).toLocaleString(),e=v=>v==null?'Pending':v.toFixed(4)+' px';document.getElementById('camera-updated').textContent=`Last published update: ${new Date(d.updated_at).toLocaleString()}`;document.getElementById('camera-results').innerHTML=`<tr><td>Original SIMPLE_RADIAL</td><td>${b.registered_images} / 500</td><td>${n(b.sparse_points)}</td><td>${e(b.reprojection_error)}</td><td>${n(b.dense_points)}</td></tr><tr><td>iPhone-aware OPENCV estimate</td><td>${n(x.metrics.registered_images)} / 500</td><td>${n(x.metrics.points3D)}</td><td>${e(x.metrics.mean_reprojection_error)}</td><td>${n(x.dense_points)}</td></tr>`;document.getElementById('camera-progress').textContent=Object.entries(x.stages).map(([k,v])=>`${k.replaceAll('_',' ')}: ${v.state}`).join(' · ');const box=document.getElementById('camera-intrinsics');for(const [label,cams,order]of[['Original',b.cameras,'f cx cy k'],['OPENCV',x.metrics.cameras,'fx fy cx cy k1 k2 p1 p2']]){const p=document.createElement('p');p.textContent=`${label} (${order}): ${cams?.length?cams.map(c=>c.params).join('; '):'Pending'}`;box.append(p)}}catch(e){document.getElementById('camera-updated').textContent=e.message}})();
